import assert from "node:assert/strict";
import { RealtimeServer } from "./src/server.ts";
const version = 2;
function rejoin() {
  const frames = [], events = [];
  const server = new RealtimeServer({tokens: new Set(["valid"]), budgetSeconds: 120,
    telemetry: e => events.push(e), respond: () => "answer"});
  const send = m => server.handle("connection", JSON.stringify(m), r => frames.push(JSON.parse(r)));
  send({type: "join", roomId: "room", token: "valid", version});
  assert.equal(frames.at(-1).type, "joined");
  const before = JSON.stringify([...server.sessions.entries()]);
  send({type: "join", roomId: "room", token: "invalid", version});
  assert.deepEqual(frames.at(-1), {type: "rejected", reason: "auth"});
  const after = JSON.stringify([...server.sessions.entries()]);
  return {rejected: true, stateUnchanged: before === after,
    sessionsBefore: JSON.parse(before).length, sessionsAfter: JSON.parse(after).length};
}
function cancellation() {
  const frames = [], events = [];
  let server;
  const send = m => server.handle("connection", JSON.stringify(m), r => frames.push(JSON.parse(r)));
  server = new RealtimeServer({tokens: new Set(["valid"]), budgetSeconds: 120,
    telemetry: e => events.push(e), respond: () => {
      send({type: "cancel", correlationId: "turn-1"});
      return "answer";
    }});
  send({type: "join", roomId: "room", token: "valid", version});
  assert.equal(frames.at(-1).type, "joined");
  send({type: "ptt", correlationId: "turn-1", pressed: true});
  send({type: "audio", correlationId: "turn-1", ms: 1, transcript: "test"});
  send({type: "ptt", correlationId: "turn-1", pressed: false});
  const ordering = events.filter(e => ["cancelled", "response"].includes(e.name)).map(e => e.name);
  assert.equal(ordering[0], "cancelled");
  return {ordering, responseFramesAfterCancel: frames.filter(f => f.type === "response").length,
    pendingAfterCancel: server.sessions.get("connection").pending};
}
console.log(JSON.stringify({rejoin: rejoin(), cancellation: cancellation()}));

